// @FIGURE_CODE_BEGIN
var draw = SVG().addTo('#container').size('100%', '100%');
var W = 720, H = 380;
draw.viewbox(0, 0, W, H);

// ── GRADIENTS ─────────────────────────────────────────────────────────────
var defs = draw.defs();
var sphereGrad = defs.gradient('radial', function(add) {
  add.stop(0, '#51b5b8');
  add.stop(0.7, '#328b8d');
  add.stop(1, '#246b6d');
});
sphereGrad.attr({ cx: '35%', cy: '35%', r: '65%' });

var selSphereGrad = defs.gradient('radial', function(add) {
  add.stop(0, '#ffd966');
  add.stop(0.7, '#e69900');
  add.stop(1, '#a66d00');
});
selSphereGrad.attr({ cx: '35%', cy: '35%', r: '65%' });

// ── LAYER GROUPS ──────────────────────────────────────────────────────────
var guidesGroup = draw.group().attr('id', 'guidesGroup').hide();
var spheresGroup = draw.group().attr('id', 'spheresGroup');
var ringsGroup = draw.group().attr('id', 'ringsGroup');
var labelsGroup = draw.group().attr('id', 'labelsGroup');

// ── DATA GENERATION ───────────────────────────────────────────────────────
var R = 15;
var D = 30; // exact neighbor distance for crystal

// 1. Crystalline Points
var crystalPts = [];
var cx0 = 180, cy0 = 160;
var rows = 7;
var dy = D * Math.sin(Math.PI / 3);

for (var r = 0; r < rows; r++) {
  var count = (r % 2 === 0) ? 8 : 7;
  var startX = cx0 - ((count - 1) * D) / 2;
  var y = cy0 + (r - (rows - 1) / 2) * dy;
  for (var c = 0; c < count; c++) {
    crystalPts.push({ x: startX + c * D, y: y });
  }
}

// 2. Amorphous Points (Seeded Relaxation)
var amorphousPts = [];
var seed = 42;
function rand() {
  seed = (seed * 1664525 + 1013904223) % 4294967296;
  return seed / 4294967296;
}

// Initial scattered disk
for (var i = 0; i < 53; i++) {
  var rDist = Math.sqrt(rand()) * 110;
  var theta = rand() * Math.PI * 2;
  amorphousPts.push({
    x: 540 + rDist * Math.cos(theta),
    y: 160 + rDist * Math.sin(theta)
  });
}

// Fast relaxation to remove major overlaps while keeping glassy disorder
for (var iter = 0; iter < 50; iter++) {
  for (var i = 0; i < 53; i++) {
    // Gentle pull to center to maintain density
    amorphousPts[i].x += (540 - amorphousPts[i].x) * 0.005;
    amorphousPts[i].y += (160 - amorphousPts[i].y) * 0.005;

    for (var j = i + 1; j < 53; j++) {
      var dx = amorphousPts[i].x - amorphousPts[j].x;
      var dyDist = amorphousPts[i].y - amorphousPts[j].y;
      var dist = Math.hypot(dx, dyDist);
      var target = 29; // Slightly less than D=30 to allow tight clumps

      if (dist < target) {
        var diff = (target - dist) * 0.5;
        var nx = (dist === 0) ? rand() : dx / dist;
        var ny = (dist === 0) ? rand() : dyDist / dist;
        amorphousPts[i].x += nx * diff; amorphousPts[i].y += ny * diff;
        amorphousPts[j].x -= nx * diff; amorphousPts[j].y -= ny * diff;
      }
    }
  }
}

// ── DRAWING ───────────────────────────────────────────────────────────────
// Draw Lattice Guides (Crystal Only)
crystalPts.forEach(function(p, i) {
  crystalPts.forEach(function(p2, j) {
    if (i < j) {
      var dist = Math.hypot(p.x - p2.x, p.y - p2.y);
      if (dist > 28 && dist < 32) {
        guidesGroup.line(p.x, p.y, p2.x, p2.y)
          .stroke({ width: 2.5, color: 'rgba(255, 230, 0, 0.8)', linecap: 'round' });
      }
    }
  });
});

// Draw Spheres
var allSpheres = [];

function renderSpheres(pts, type) {
  pts.forEach(function(p, idx) {
    var circle = spheresGroup.circle(R * 2).center(p.x, p.y)
      .fill(sphereGrad)
      .stroke({ width: 1, color: '#216163' })
      .css('cursor', 'pointer');

    var data = { circle: circle, p: p, type: type, idx: idx };
    allSpheres.push(data);

    circle.on('click', function() {
      selectParticle(data);
    });

    circle.on('mousemove', function(e) {
      showTooltip(type === 'crystal' ? 'Crystalline Particle' : 'Amorphous Particle', e);
    });
    circle.on('mouseleave', function() {
      hideTooltip();
    });
  });
}
renderSpheres(crystalPts, 'crystal');
renderSpheres(amorphousPts, 'amorphous');

// Draw Labels
labelsGroup.text('Crystalline')
  .font({ size: 18, family: 'sans-serif', fill: '#111', anchor: 'middle' })
  .attr({ x: 180, y: 320 });

labelsGroup.text('Amorphous')
  .font({ size: 18, family: 'sans-serif', fill: '#111', anchor: 'middle' })
  .attr({ x: 540, y: 320 });

// ── INTERACTIONS ──────────────────────────────────────────────────────────
var activeSelections = [];

function selectParticle(data) {
  // Clear previous selection for this specific type (crystal or amorphous)
  activeSelections = activeSelections.filter(function(sel) {
    if (sel.type === data.type) {
      sel.ring.remove();
      return false;
    }
    return true;
  });

  // Create a new distance ring marker
  var ring = ringsGroup.circle(D * 2).center(data.p.x, data.p.y)
    .fill('none')
    .stroke({ width: 2.5, color: '#f39c12', dasharray: '6,4' });

  activeSelections.push({
    type: data.type,
    ring: ring
  });

  // Update styling for all spheres of this type to emphasize local neighborhood
  allSpheres.filter(function(s) { return s.type === data.type; }).forEach(function(s) {
    if (s === data) {
      // The selected sphere itself
      s.circle.fill(selSphereGrad).stroke({ width: 2, color: '#a05000' });
    } else {
      var dist = Math.hypot(s.p.x - data.p.x, s.p.y - data.p.y);
      if (dist > 15 && dist < 48) {
        // Immediate neighbor shell
        s.circle.fill(sphereGrad).stroke({ width: 2.5, color: '#f39c12' });
      } else {
        // Unaffected sphere
        s.circle.fill(sphereGrad).stroke({ width: 1, color: '#216163' });
      }
    }
  });
}

window.clearAllSelections = function() {
  activeSelections.forEach(function(sel) { sel.ring.remove(); });
  activeSelections = [];
  allSpheres.forEach(function(s) {
    s.circle.fill(sphereGrad).stroke({ width: 1, color: '#216163' });
  });
};

window.toggle_latticeGuides = function(on) {
  if (on) guidesGroup.show();
  else guidesGroup.hide();
  document.getElementById('latticeGuidesInput').checked = on;
};

// ── DEMO STEP PLAYER ──────────────────────────────────────────────────────
var steps = [
  {
    title: "Comparing macroscopic density",
    narration: "Both solids pack particles closely together at roughly the same density, but their internal organization is fundamentally different.",
    state: { latticeGuides: false }
  },
  {
    title: "Long-range order",
    narration: "Turning on the lattice guides reveals continuous, unbroken rows and diagonals in the crystalline solid. The amorphous solid has no such repeating pathways.",
    state: { latticeGuides: true }
  },
  {
    title: "Local neighborhoods",
    narration: "Click on individual particles in both solids to compare their immediate surroundings. The crystalline solid has perfectly uniform local geometry, while the amorphous solid's gaps and clusters create unique environments for each particle.",
    state: { latticeGuides: false },
    action: function() {
      // Simulate click on central particles to immediately show the contrast
      var cIdx = getCenterParticleIndex(crystalPts, cx0, cy0);
      var aIdx = getCenterParticleIndex(amorphousPts, 540, 160);

      var cData = allSpheres.filter(function(s) { return s.type === 'crystal' && s.idx === cIdx; })[0];
      var aData = allSpheres.filter(function(s) { return s.type === 'amorphous' && s.idx === aIdx; })[0];

      if (cData) selectParticle(cData);
      if (aData) selectParticle(aData);
    }
  }
];

function getCenterParticleIndex(pts, cx, cy) {
  var bestIdx = 0;
  var minDist = Infinity;
  pts.forEach(function(p, i) {
    var dist = Math.hypot(p.x - cx, p.y - cy);
    if (dist < minDist) {
      minDist = dist;
      bestIdx = i;
    }
  });
  return bestIdx;
}

var currentStep = 0;

function applyStep(idx) {
  var s = steps[idx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = "Step " + (idx + 1) + " / " + steps.length;

  window.toggle_latticeGuides(s.state.latticeGuides);

  if (s.action) {
    s.action();
  } else {
    window.clearAllSelections();
  }

  document.getElementById('btnPrev').disabled = (idx === 0);
  document.getElementById('btnNext').disabled = (idx === steps.length - 1);
}

window.prevStep = function() {
  if (currentStep > 0) {
    currentStep--;
    applyStep(currentStep);
  }
};

window.nextStep = function() {
  if (currentStep < steps.length - 1) {
    currentStep++;
    applyStep(currentStep);
  }
};

// Initialize
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

