  <input id="latticeGuidesInput" type="checkbox" onchange="toggle_latticeGuides(this.checked)">
  Lattice guides
</label>

<div style="margin-top: 16px; font-size: 11px; color: #444; background: #f4f6f8; padding: 10px; border-radius: 6px; border: 1px solid #dcdfe3; line-height: 1.4;">
