// Slightly widened to allow the same number of spheres to fit loosely, creating voids.
var boxMinX = 410, boxMaxX = 670;
var boxMinY = 70, boxMaxY = 210;

for (var i = 0; i < 51; i++) {
  amorphousPts.push({
    x: boxMinX + rand() * (boxMaxX - boxMinX),
    y: boxMinY + rand() * (boxMaxY - boxMinY)
