}

// Relaxation to remove major overlaps while keeping glassy disorder & internal gaps
for (var iter = 0; iter < 150; iter++) {
  for (var i = 0; i < amorphousPts.length; i++) {
    for (var j = i + 1; j < amorphousPts.length; j++) {
